@using sv_b30ca29403224ae78945f8edcb61a7c7.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h2>Profile</h2>

    @if (_loading)
    {
        <p class="text-muted">Loading profile…</p>
    }
    else
    {
        <div class="profile-form">
            <div class="avatar-area">
                <div class="avatar-preview">
                    @if (!string.IsNullOrWhiteSpace(_displayAvatarUrl))
                    {
                        <img src="@_displayAvatarUrl" alt="Avatar" />
                    }
                    else
                    {
                        <span class="avatar-placeholder">👤</span>
                    }
                </div>
                <div class="avatar-url-display">
                    <label>Avatar URL</label>
                    <span class="text-muted small">@(_displayAvatarUrl ?? "No avatar set")</span>
                </div>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" class="form-control" @bind="_displayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" class="form-control" @bind="_email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" class="form-control" rows="4" @bind="_bio"></textarea>
            </div>

            <div class="form-actions">
                <button type="button" class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save Changes")
                </button>
                <button type="button" class="btn btn-outline-secondary" @onclick="DiscardChanges">
                    Discard Changes
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="alert alert-success mt-3" role="alert">Profile saved successfully!</div>
            }
        </div>
    }
</section>

@code {
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private UserProfile? _savedProfile;
    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _displayAvatarUrl = "";

    protected override async Task OnInitializedAsync()
    {
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _bio = profile.Bio;
        _displayAvatarUrl = profile.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;

        var updated = new UserProfile(_displayName, _email, _displayAvatarUrl, _bio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;

        _saving = false;
        _showSuccess = true;
    }

    private void DiscardChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
        _showSuccess = false;
    }
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
}

