arguments.file_text:
@using sv_b30ca29403224ae78945f8edcb61a7c7.Services
@inject ISettingsService SettingsService

<div class="password-panel">
    <button type="button" class="panel-toggle" @onclick="() => _expanded = !_expanded">
        <span>🔑 Change Password</span>
        <span class="toggle-indicator">@(_expanded ? "▲" : "▼")</span>
    </button>

    @if (_expanded)
    {
        <div class="panel-body">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" class="form-control" @bind="_currentPassword" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" class="form-control" @bind="_newPassword" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" class="form-control" @bind="_confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(_errorMessage))
            {
                <div class="alert alert-danger" role="alert">@_errorMessage</div>
            }

            @if (_showSuccess)
            {
                <div class="alert alert-success" role="alert">Password updated successfully!</div>
            }

            <button type="button" class="btn btn-primary" @onclick="UpdatePasswordAsync" disabled="@_saving">
                @(_saving ? "Updating…" : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    private bool _expanded;
    private bool _saving;
    private bool _showSuccess;
    private string _errorMessage = "";

    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";

    private async Task UpdatePasswordAsync()
    {
        _errorMessage = "";
        _showSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _errorMessage = "Current password is required.";
            return;
        }

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _errorMessage = "New password is required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _errorMessage = "New password and confirmation do not match.";
            return;
        }

        _saving = true;

        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _showSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
}

.password-panel {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-toggle {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 1rem 1.25rem;
    border: none;
    background: #f8f9fa;
    font-size: 1rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.15s;
}

.panel-toggle:hover {
    background: #e9ecef;
}

.toggle-indicator {
    font-size: 0.8rem;
    color: #6c757d;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #dee2e6;
}

.panel-body .form-group {
    margin-bottom: 1rem;
}

.panel-body .form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
}

@using sv_b30ca29403224ae78945f8edcb61a7c7.Services

<div class="sessions-section">
    <h4>Active Sessions</h4>

    @if (Sessions.Count == 0)
    {
        <p class="text-muted">No active sessions.</p>
    }
    else
    {
        <table class="table table-hover sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("MMM d, yyyy h:mm tt")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button type="button"
                                        class="btn btn-sm btn-outline-danger"
                                        @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="badge bg-success">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }

    @if (_sessionToRevoke is not null)
    {
        <div class="modal-backdrop" @onclick="CancelRevoke">
            <div class="confirm-dialog" @onclick:stopPropagation="true">
                <h5>Revoke Session</h5>
                <p>
                    Are you sure you want to revoke the session on
                    <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?
                </p>
                <div class="dialog-actions">
                    <button type="button" class="btn btn-danger" @onclick="ConfirmRevokeAsync" disabled="@_revoking">
                        @(_revoking ? "Revoking…" : "Revoke")
                    </button>
                    <button type="button" class="btn btn-outline-secondary" @onclick="CancelRevoke" disabled="@_revoking">
                        Cancel
                    </button>
                </div>
            </div>
        </div>
    }
