+                <div class="alert alert-success" role="alert">Password updated successfully!</div>
+            }
+
+            <button type="button" class="btn btn-primary" @onclick="UpdatePasswordAsync" disabled="@_saving">
+                @(_saving ? "Updating…" : "Update Password")
+            </button>
+        </div>
+    }
+</div>
+
+@code {
+    private bool _expanded;
+    private bool _saving;
+    private bool _showSuccess;
+    private string _errorMessage = "";
+
+    private string _currentPassword = "";
+    private string _newPassword = "";
+    private string _confirmPassword = "";
+
+    private async Task UpdatePasswordAsync()
+    {
+        _errorMessage = "";
+        _showSuccess = false;
+
+        if (string.IsNullOrWhiteSpace(_currentPassword))
+        {
+            _errorMessage = "Current password is required.";
+            return;
+        }
+
+        if (string.IsNullOrWhiteSpace(_newPassword))
+        {
+            _errorMessage = "New password is required.";
+            return;
+        }
+
+        if (_newPassword != _confirmPassword)
+        {
+            _errorMessage = "New password and confirmation do not match.";
+            return;
+        }
+
+        _saving = true;
+
+        try
+        {
+            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
+            _showSuccess = true;
+            _currentPassword = "";
+            _newPassword = "";
+            _confirmPassword = "";
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = ex.Message;
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+}
+

