toolArgs.file_text:
.appearance-form {
    max-width: 600px;
}

.setting-group {
    margin-bottom: 1.75rem;
}

.setting-group h4 {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 0.75rem;
}

.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    padding: 0.5rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    transition: border-color 0.15s, background-color 0.15s;
}

.radio-option:hover {
    background: #f8f9fa;
}

.radio-option:has(input:checked) {
    border-color: #0d6efd;
    background: #e7f1ff;
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border: 1px solid #e9ecef;
    border-radius: 0.375rem;
    cursor: pointer;
}

.toggle-switch {
    width: 2.5rem !important;
    height: 1.25rem;
    cursor: pointer;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Preview area */
.preview-area {
    margin-top: 2rem;
}

.preview-area h4 {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 0.75rem;
}

.preview-box {
    padding: 1.5rem;
    border-radius: 0.5rem;
    border: 1px solid #dee2e6;
    transition: all 0.2s;
}

.preview-header {
    font-weight: 700;
    margin-bottom: 0.75rem;
}

.preview-text {
    margin-bottom: 1rem;
    line-height: 1.6;
}

.preview-actions {
    display: flex;
    gap: 0.5rem;
}

.preview-btn {
    padding: 0.375rem 1rem;
    border-radius: 0.375rem;
    border: 1px solid transparent;
    cursor: default;
    font-size: inherit;
}

.preview-btn.primary {
    background: #0d6efd;
    color: #fff;
}

.preview-btn.secondary {
    background: transparent;
    border-color: #6c757d;
    color: #6c757d;
}

/* Theme variations */
.preview-theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-theme-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-theme-dark .preview-btn.secondary {
    border-color: #89b4fa;
    color: #89b4fa;
}

.preview-theme-system {
    background: #f8f9fa;
    color: #212529;
}

/* Font size variations */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-small .preview-header {
    font-size: 1rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-medium .preview-header {
    font-size: 1.25rem;
}

